 int ok;
 if(report==NULL)report=&ignored;
 if(values==NULL||count==NULL){report->malformed=1;
 return 0;
 }capacity=*count;
 *count=0;
 bodies=graphdemo_table_message_open(&r,vocabulary,buffer,bytes,report);
